mapper.select:

select d.*, c.name as categoryName
from dish d
left join category c on d.category_id = c.id and c.tenant_id = d.tenant_id

    d.tenant_id = #{scopeTenant}

        and d.name like CONCAT('%', #{name}, '%')


        and d.category_id = #{categoryId}


        and d.status = #{status}


order by d.create_time desc


select * from dish

    tenant_id = #{scopeTenant}
    and category_id = #{categoryId}
    and status = #{status}

order by create_time desc, id desc

mapper.delete:

delete from dish where tenant_id = #{scopeTenant} and id in

    #{id}


and (select count(*) from (select id, tenant_id from dish group by id, tenant_id) owned where owned.tenant_id = #{scopeTenant} and owned.id in
#{requestedId}) = #{requestedCount}
